class Depends:
    dependency: Optional[Callable[..., Any]] = None
    use_cache: bool = True
    scope: Union[Literal["function", "request"], None] = None

    def __hash__(self):
        if self.dependency is None:
            dep_hash = None
        else:
            try:
                dep_hash = hash(self.dependency)
            except TypeError:
                dep_hash = id(self.dependency)
        return hash((dep_hash, self.use_cache, self.scope))

